            int by_end = by_start + blockDim.y;
            int i = tid + bx_start * blockDim.y;
            int j = tid + by_start * blockDim.x;
            int col = j / blockDim.x;
            int row = i / blockDim.y;
            if (col >= n_cols) return;
            if (row >= n_rows) return;
            float val = W[col][row];
            if (skip_below && val < skip_below) continue;
            y[i * n_cols + j] = val;
          }
